+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/** Immutable criteria shared by the backend page and count queries. */
+public record CustomerFilter(List<String> terms, Set<CustomerStatus> statuses) implements Serializable {
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    public static final CustomerFilter EMPTY = new CustomerFilter(List.of(), Set.of());
+
+    public CustomerFilter {
+        terms = List.copyOf(terms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    public static CustomerFilter of(String name, Set<CustomerStatus> statuses) {
+        return new CustomerFilter(WHITESPACE.splitAsStream(normalize(name))
+                .filter(term -> !term.isEmpty()).toList(), statuses);
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private static String normalize(String value) {
+        return MARKS.matcher(Normalizer.normalize(value, Normalizer.Form.NFD))
+                .replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
